  panel.locator('[data-stage-field=mode][value=auto]').check();expect(panel.locator('[data-stage-auto]')).to_be_visible();expect(panel.locator('[data-stage-field=position][value=before]')).to_be_checked();panel.locator('[data-stage-save]').click();expect(panel.locator('[data-stage-direction-status]')).to_contain_text('Settings loaded');assert page.evaluate('saved.global.mode')=='auto'
