  assert page.evaluate('''()=>{const root=ctx.dom.listMessageElements()[0].element.firstElementChild,snap=T.theaterSnapshot('s',root);return T.theaterLiveVerified(snap,'[[scene: kitchen]]\\n[[lighting: moon').length===1&&T.theaterLiveVerified(snap,raw).length===4}''')
